-- Cooper portal menus only. Additive, idempotent seed; no existing project rows are modified.
SET AUTOCOMMIT OFF;
WHENEVER SQLERROR EXIT ROLLBACK;
COMMIT;
SELECT "rule_code","title","path","component" FROM "rbac_rule" WHERE "project"='cooper' ORDER BY "weigh";

UPDATE "rbac_rule" SET "menu_type"='Link',"url"='/preview/news' WHERE "project"='cooper' AND "rule_code"='portal/preview/news';
UPDATE "rbac_rule" SET "menu_type"='Link',"url"='/preview/notice' WHERE "project"='cooper' AND "rule_code"='portal/preview/notice';
UPDATE "rbac_rule" SET "menu_type"='Link',"url"='/preview/office' WHERE "project"='cooper' AND "rule_code"='portal/preview/office';
COMMIT;
